{
  "$schema": "https://open-design.ai/schemas/plugin.v1.json",
  "specVersion": "1.0.0",
  "name": "video-template-frame-bold-poster",
  "title": "Bold Poster Frame",
  "title_i18n": {
    "en": "Bold Poster Frame",
    "zh-CN": "大胆海报帧"
  },
  "version": "0.1.0",
  "publishedAt": "2026-06-11T09:17:17Z",
  "description": "A 1970s European editorial poster in motion — a red rule draws across, a giant tilted figure drops in, a three-line headline rises line-by-line, an italic serif standfirst fades.",
  "description_i18n": {
    "en": "A 1970s European editorial poster in motion — a red rule draws across, a giant tilted figure drops in, a three-line headline rises line-by-line, an italic serif standfirst fades.",
    "zh-CN": "大胆海报帧:1970s 欧洲社论海报风 + 番红强调色 + 巨型倾斜 Shrikhand 大字 + 三行标题逐行升起 + 衬线斜体副题, 印刷质感强。"
  },
  "license": "Apache-2.0",
  "author": {
    "name": "nexu-io",
    "url": "https://github.com/nexu-io",
    "contact": "open-design@nexu.io"
  },
  "homepage": "https://github.com/nexu-io/html-video/tree/main/templates/frame-bold-poster",
  "tags": [
    "video-template",
    "first-party",
    "video",
    "hyperframes",
    "html-video",
    "motion",
    "poster",
    "editorial",
    "bold",
    "serif",
    "red",
    "print",
    "manifesto",
    "tilted",
    "high-impact",
    "presentation"
  ],
  "compat": {
    "agentSkills": [
      {
        "path": "./SKILL.md"
      }
    ]
  },
  "od": {
    "kind": "scenario",
    "taskKind": "new-generation",
    "mode": "video",
    "scenario": "video",
    "surface": "hyperframes",
    "engine": "hyperframes",
    "preview": {
      "type": "video",
      "poster": "https://cdn.jsdelivr.net/gh/nexu-io/open-design@main/plugins/_official/video-templates/frame-bold-poster/preview.png",
      "video": "https://cdn.jsdelivr.net/gh/nexu-io/open-design@main/plugins/_official/video-templates/frame-bold-poster/preview.mp4"
    },
    "useCase": {
      "query": {
        "en": "Use the Bold Poster Frame template to open my deck like a magazine cover — a mono kicker with a red rule drawing across, a giant tilted display figure, a three-line headline rising line-by-line (the middle line in red), and an italic serif standfirst. Preserve the template's print-poster signature, use real content, and avoid lorem ipsum or placeholder images.",
        "zh-CN": "用「大胆海报帧」模板把我的开场做成杂志封面感:mono kicker + 红线划过 + 巨型倾斜大字 + 三行标题逐行升起(中间行番红)+ 衬线斜体副题。保持印刷海报的视觉签名,使用真实内容,避免 lorem ipsum 和占位图片。"
      }
    },
    "inputs": [
      {
        "name": "aspect",
        "label": "Aspect ratio",
        "type": "select",
        "options": [
          "16:9"
        ],
        "default": "16:9"
      },
      {
        "name": "format",
        "label": "Output format",
        "type": "select",
        "options": [
          "mp4",
          "webm"
        ],
        "default": "mp4"
      },
      {
        "name": "durationSec",
        "label": "Duration (seconds)",
        "type": "number",
        "default": 15
      }
    ],
    "context": {
      "skills": [
        {
          "path": "./SKILL.md"
        }
      ],
      "assets": [
        "./template.json",
        "./source"
      ]
    },
    "pipeline": {
      "stages": [
        {
          "id": "compose",
          "atoms": [
            "file-write"
          ]
        },
        {
          "id": "render",
          "atoms": [
            "media-video"
          ]
        }
      ]
    },
    "capabilities": [
      "prompt:inject",
      "fs:write",
      "media:video-generate"
    ],
    "provenance": {
      "origin": {
        "name": "1970s European editorial / poster tradition",
        "kind": "movement",
        "reference": "No single studio — the upstream template names vintage Italian sports magazines, mid-century European brand annual reports, and wine-merchant catalogues as its visual lineage. Recorded as a tradition, not a specific firm.\n"
      },
      "via_skill": {
        "name": "frontend-slides",
        "author": "Zara Zhang",
        "url": "https://github.com/zarazhangrui/frontend-slides",
        "license": "MIT",
        "source_file": "bold-template-pack/templates/bold-poster/design.md"
      },
      "transformation": "Static slide design spec → animated hyperframes timeline (red kicker rule draws in, a giant Shrikhand figure rotates + drops, a three-line headline rises line-by-line each tilted, an italic serif standfirst fades, an ink footer rule draws in) built as original CSS keyframes. Palette (#FFFFFF / #1C1410 / #D8000F / #F5F2EF) and the three-face type stack (Shrikhand / Libre Baskerville / Space Grotesk) follow the upstream spec; sample copy is original; no upstream source HTML copied verbatim.\n"
    }
  }
}

